package am.ik.yavi.builder

import am.ik.yavi.arguments.Arguments1
import am.ik.yavi.constraint.EnumConstraint
import am.ik.yavi.constraint.ObjectConstraint

/*
 * The extensions on the ArgumentsNValidatorBuilder types make the reified form available
 * for the second and the following argument of a schema. Keep them in sync with the
 * builder types generated by scripts/generate-args.sh.
 *
 * A schema adds one argument at a time, so the receiver of these extensions is the
 * builder for the arguments that have already been added. Kotlin accepts no partial type
 * argument list, so the reified type has to be the only type parameter and the types of
 * the added arguments cannot be named here. Their input types become Any, which accepts
 * any raw value, and their validated types Nothing, which accepts any function given to
 * apply or fromMap. The builders still carry the real types, so the validated values are
 * the expected ones. Give the constructor as a method reference, such as apply(::Account):
 * a lambda would take the values of the added arguments as Nothing.
 */

/**
 * Adds the next argument as a constant of the reified enum type [E] with the given name
 * and configured constraints.
 *
 * @param E the enum type of the argument
 * @param name the property name used in violation names and messages
 * @return a builder for the next argument
 * @since 0.18.0
 */
@Suppress("UNCHECKED_CAST")
inline fun <reified E : Enum<E>> Arguments1ValidatorBuilder<*, *>._enum(
    name: String,
    noinline constraints: (EnumConstraint<Arguments1<E>, E>) -> EnumConstraint<Arguments1<E>, E>
): Arguments2ValidatorBuilder.Added<Any, E, Nothing, E> = this._enum(name, E::class.java, constraints) as Arguments2ValidatorBuilder.Added<Any, E, Nothing, E>

/**
 * Adds the next argument as a constant of the reified enum type [E] with the given name and
 * no constraints.
 *
 * @param E the enum type of the argument
 * @param name the property name recorded for the argument
 * @return a builder for the next argument
 * @since 0.18.0
 */
@Suppress("UNCHECKED_CAST")
inline fun <reified E : Enum<E>> Arguments1ValidatorBuilder<*, *>._enum(name: String): Arguments2ValidatorBuilder.Added<Any, E, Nothing, E> =
    this._enum(name, E::class.java) as Arguments2ValidatorBuilder.Added<Any, E, Nothing, E>

